 const strictHeatFlag=pendingPieces(bothDeferred('MTR_FLAG_ONLY'));delete strictHeatFlag.traceability.heat_required_for_receiving;delete strictHeatFlag.arrival.pass_blockers;await context.FabSpoolBom.open(descriptor('MTR_FLAG_ONLY'));const beforeStrictHeatFlag=writes().length;chooseQa('2-1','Pass');await action('qa-save',{fbomPiece:'2-1'});assert.match(html(),/Enter this piece’s heat number/);assert.doesNotMatch(html(),/Enter this piece’s MTR reference/);await action('qa-pass-all');await action('qa-confirm-pass-all');await action('inspection-panel');chooseArrival('Pass');checkArrival();await saveArrival();assert.equal(writes().length,beforeStrictHeatFlag);assert.match(html(),/Save a heat number for every material piece/);assert.doesNotMatch(html(),/Save an MTR reference for every material piece/);
 checks.push('Deferral flags are independent: permitting MTR deferral never waives heat for an older or strict heat policy');

 const mixedHistory=bothDeferred('MTR_SNAPSHOT_HISTORY');mixedHistory.arrival.history=[{version:2,result:'Pass',actor:'QA',checks:{identity:true,bom:true,condition:true,heat_numbers:false,mtrs:false},checks_catalog:[{key:'identity',label:'Original identity review'},{key:'bom',label:'Original BOM review'},{key:'condition',label:'Original condition review'}],deferred_checks:['heat_numbers','mtrs'],heat_deferral:{required_at_label:'Saved heat gate'},mtr_deferral:{required_at_label:'Saved MTR gate'}},{version:1,result:'Pass',actor:'QA',checks:{identity:true,bom:true,heat_numbers:false,mtrs:true,condition:true},checks_catalog:[{key:'mtrs',label:'Original actual-MTR review'}],deferred_checks:['heat_numbers']}];await context.FabSpoolBom.open(descriptor('MTR_SNAPSHOT_HISTORY'));assert.match(html(),/MTR verification was deferred until Saved MTR gate/);assert.match(html(),/Heat-number verification was deferred until Saved heat gate/);assert.match(html(),/Original actual-MTR review: Confirmed/);assert.equal((html().match(/MTR verification was deferred/g)||[]).length,1);assert.doesNotMatch(html(),/(?:mtrs|heat_numbers): Not confirmed/);
 checks.push('History preserves the original independent heat/MTR deferrals and checklist labels without rewriting prior actual MTR verification');

 const blankChanged=pendingPieces(bothDeferred('BOTH_BLANK_CHANGED'));blankChanged.source_status.changed=true;blankChanged.arrival.pass_blockers=['The effective BOM has changed. Adopt and review its current revision for this spool.'];await context.FabSpoolBom.open(descriptor('BOTH_BLANK_CHANGED'));const beforeBlankChanged=writes().length;chooseQa('2-1','Pass');await action('qa-save',{fbomPiece:'2-1'});await action('qa-pass-all');await action('qa-confirm-pass-all');await action('inspection-panel');chooseArrival('Pass');checkArrival();await saveArrival();assert.equal(writes().length,beforeBlankChanged);assert.equal(blankChanged.arrival.version,0);assert.ok(blankChanged.traceability.materials.every(row=>!row.qa001.can_proceed));
